// then it first copies the existing relationships from the old model to the new model
// and then replaces the old model in the slice with the new model
func (o BudgetSlice) copyMatchingRows(from ...*Budget) {
	fromByPK := make(map[uuid.UUID]*Budget, len(from))
	for _, new := range from {
		// keep the first row for each key, like the nested loop did
		if _, ok := fromByPK[new.ID]; !ok {
			fromByPK[new.ID] = new
		}
	}

	for i, old := range o {
		new, ok := fromByPK[old.ID]
		if !ok {
			continue
		}
		new.R = old.R
		o[i] = new
	}
}

// UpdateMod modifies an update query with "WHERE primary_key IN (o...)"
func (o BudgetSlice) UpdateMod() bob.Mod[*dialect.UpdateQuery] {
	return bob.ModFunc[*dialect.UpdateQuery](func(q *dialect.UpdateQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Budgets.BeforeUpdateHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Budget:
				o.copyMatchingRows(retrieved)
			case []*Budget:
				o.copyMatchingRows(retrieved...)
			case BudgetSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Budget or a slice of Budget
				// then run the AfterUpdateHooks on the slice
				_, err = Budgets.AfterUpdateHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))

		q.AppendWhere(o.pkIN())
	})
}

// DeleteMod modifies an delete query with "WHERE primary_key IN (o...)"
func (o BudgetSlice) DeleteMod() bob.Mod[*dialect.DeleteQuery] {
	return bob.ModFunc[*dialect.DeleteQuery](func(q *dialect.DeleteQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Budgets.BeforeDeleteHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Budget:
				o.copyMatchingRows(retrieved)
			case []*Budget:
				o.copyMatchingRows(retrieved...)
			case BudgetSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Budget or a slice of Budget
				// then run the AfterDeleteHooks on the slice
				_, err = Budgets.AfterDeleteHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))

		q.AppendWhere(o.pkIN())
	})
}

// MergeMod modifies a merge query to run BeforeMergeHooks and AfterMergeHooks
// and updates the slice with the returned rows.
func (o BudgetSlice) MergeMod() bob.Mod[*dialect.MergeQuery] {
	return bob.ModFunc[*dialect.MergeQuery](func(q *dialect.MergeQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Budgets.BeforeMergeHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Budget:
				o.copyMatchingRows(retrieved)
			case []*Budget:
				o.copyMatchingRows(retrieved...)
			case BudgetSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Budget or a slice of Budget
				// then run the AfterMergeHooks on the slice
				_, err = Budgets.AfterMergeHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))
	})
}

func (o BudgetSlice) UpdateAll(ctx context.Context, exec bob.Executor, vals BudgetSetter) error {
	if len(o) == 0 {
		return nil
	}

	_, err := Budgets.Update(vals.UpdateMod(), o.UpdateMod()).All(ctx, exec)
	return err
}

func (o BudgetSlice) DeleteAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	_, err := Budgets.Delete(o.DeleteMod()).Exec(ctx, exec)
	return err
}

func (o BudgetSlice) ReloadAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	o2, err := Budgets.Query(sm.Where(o.pkIN())).All(ctx, exec)
	if err != nil {
		return err
	}

	o.copyMatchingRows(o2...)

	return nil
}

// Category starts a query for related objects on categories
func (o *Budget) Category(mods ...bob.Mod[*dialect.SelectQuery]) CategoriesQuery {
	return Categories.Query(append(mods,
		sm.Where(Categories.Columns.HouseholdID.EQ(psql.Arg(o.HouseholdID))), sm.Where(Categories.Columns.ID.EQ(psql.Arg(o.CategoryID))),
	)...)
}

func (os BudgetSlice) Category(mods ...bob.Mod[*dialect.SelectQuery]) CategoriesQuery {
	pkHouseholdID := make(pgtypes.Array[uuid.UUID], 0, len(os))

	pkCategoryID := make(pgtypes.Array[sql.Null[uuid.UUID]], 0, len(os))

	for _, o := range os {
		if o == nil {
			continue
		}
		pkHouseholdID = append(pkHouseholdID, o.HouseholdID)
		pkCategoryID = append(pkCategoryID, o.CategoryID)
	}

	return Categories.Query(append(mods,
		sm.InnerJoin(psql.Select(
			sm.Distinct(),
			sm.Columns(psql.Quote("bob_rel_keys_src", "HouseholdID"), psql.Quote("bob_rel_keys_src", "ID")),
			sm.From(psql.F("unnest", psql.Cast(psql.Arg(pkHouseholdID), "uuid[]"), psql.Cast(psql.Arg(pkCategoryID), "uuid[]"))).As("bob_rel_keys_src", "HouseholdID", "ID"),
		)).As("bob_rel_keys").On(Categories.Columns.HouseholdID.EQ(psql.Quote("bob_rel_keys", "HouseholdID")), Categories.Columns.ID.EQ(psql.Quote("bob_rel_keys", "ID"))),
	)...)
}

// Household starts a query for related objects on households
func (o *Budget) Household(mods ...bob.Mod[*dialect.SelectQuery]) HouseholdsQuery {
	return Households.Query(append(mods,
		sm.Where(Households.Columns.ID.EQ(psql.Arg(o.HouseholdID))),
	)...)
}

func (os BudgetSlice) Household(mods ...bob.Mod[*dialect.SelectQuery]) HouseholdsQuery {
	pkHouseholdID := make(pgtypes.Array[uuid.UUID], 0, len(os))

	// the array is only a filter (semi-join), so duplicate keys can be
	// dropped before they are sent over the wire
	seenHouseholdID := make(map[uuid.UUID]struct{}, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		if _, ok := seenHouseholdID[o.HouseholdID]; ok {
			continue
		}
		seenHouseholdID[o.HouseholdID] = struct{}{}
		pkHouseholdID = append(pkHouseholdID, o.HouseholdID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkHouseholdID), "uuid[]"))

	return Households.Query(append(mods,
		sm.Where(Households.Columns.ID.EQ(PKArgExpr)),
	)...)
}

func attachBudgetCategory0(ctx context.Context, exec bob.Executor, count int, budget0 *Budget, category1 *Category) (*Budget, error) {
	setter := &BudgetSetter{
		HouseholdID: func() *uuid.UUID { return &category1.HouseholdID }(),
		CategoryID:  func() *sql.Null[uuid.UUID] { v := sql.Null[uuid.UUID]{V: category1.ID, Valid: true}; return &v }(),
	}

	err := budget0.Update(ctx, exec, setter)
	if err != nil {
		return nil, fmt.Errorf("attachBudgetCategory0: %w", err)
	}

	return budget0, nil
}

func (budget0 *Budget) InsertCategory(ctx context.Context, exec bob.Executor, related *CategorySetter) error {
	var err error

	category1, err := Categories.Insert(related).One(ctx, exec)
	if err != nil {
		return fmt.Errorf("inserting related objects: %w", err)
	}

	_, err = attachBudgetCategory0(ctx, exec, 1, budget0, category1)
	if err != nil {
		return err
	}

	budget0.R.Category = category1
	budget0.R.Loaded.Category = true

	category1.R.Budgets = append(category1.R.Budgets, budget0)

	return nil
}

func (budget0 *Budget) AttachCategory(ctx context.Context, exec bob.Executor, category1 *Category) error {
	var err error

	_, err = attachBudgetCategory0(ctx, exec, 1, budget0, category1)
	if err != nil {
		return err
	}

	budget0.R.Category = category1
	budget0.R.Loaded.Category = true

	category1.R.Budgets = append(category1.R.Budgets, budget0)

	return nil
}

