type budgetWhere[Q psql.Filterable] struct {
	cols        budgetColumns
	ID          psql.WhereMod[Q, uuid.UUID]
	HouseholdID psql.WhereMod[Q, uuid.UUID]
	CategoryID  psql.WhereNullMod[Q, uuid.UUID]
	Name        psql.WhereMod[Q, string]
	AmountYen   psql.WhereMod[Q, int64]
	StartsOn    psql.WhereMod[Q, time.Time]
	EndsOn      psql.WhereNullMod[Q, time.Time]
	Archived    psql.WhereMod[Q, bool]
	Revision    psql.WhereMod[Q, int64]
	CreatedAt   psql.WhereMod[Q, time.Time]
	UpdatedAt   psql.WhereMod[Q, time.Time]
	R           budgetWhereR[Q]
}

func (budgetWhere[Q]) AliasedAs(alias string) budgetWhere[Q] {
	return buildBudgetWhere[Q](buildBudgetColumns(alias))
}

func buildBudgetWhere[Q psql.Filterable](cols budgetColumns) budgetWhere[Q] {
	return budgetWhere[Q]{
		cols:        cols,
		ID:          psql.Where[Q, uuid.UUID](cols.ID.Expression),
		HouseholdID: psql.Where[Q, uuid.UUID](cols.HouseholdID.Expression),
		CategoryID:  psql.WhereNull[Q, uuid.UUID](cols.CategoryID.Expression),
		Name:        psql.Where[Q, string](cols.Name.Expression),
		AmountYen:   psql.Where[Q, int64](cols.AmountYen.Expression),
		StartsOn:    psql.Where[Q, time.Time](cols.StartsOn.Expression),
		EndsOn:      psql.WhereNull[Q, time.Time](cols.EndsOn.Expression),
		Archived:    psql.Where[Q, bool](cols.Archived.Expression),
		Revision:    psql.Where[Q, int64](cols.Revision.Expression),
		CreatedAt:   psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		UpdatedAt:   psql.Where[Q, time.Time](cols.UpdatedAt.Expression),
		R:           budgetWhereR[Q]{cols: cols},
	}
}

// budgetWhereR holds the relationship-based filters of
// budgetWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type budgetWhereR[Q psql.Filterable] struct {
	cols budgetColumns
}

// HasCategory filters parents that have a matching Category using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Categories).
func (w budgetWhereR[Q]) HasCategory(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Categories.NameExpr()),
		sm.Where(Categories.Columns.HouseholdID.EQ(w.cols.HouseholdID)),
		sm.Where(Categories.Columns.ID.EQ(w.cols.CategoryID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// HasHousehold filters parents that have a matching Household using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Households).
func (w budgetWhereR[Q]) HasHousehold(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Households.NameExpr()),
		sm.Where(Households.Columns.ID.EQ(w.cols.HouseholdID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

func (o *Budget) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Category":
		rel, ok := retrieved.(*Category)
		if !ok {
			return fmt.Errorf("budget cannot load %T as %q", retrieved, name)
		}

		o.R.Category = rel
		o.R.Loaded.Category = true

		if rel != nil {
			rel.R.Budgets = BudgetSlice{o}
		}
		return nil
	case "Household":
		rel, ok := retrieved.(*Household)
		if !ok {
			return fmt.Errorf("budget cannot load %T as %q", retrieved, name)
		}

		o.R.Household = rel
		o.R.Loaded.Household = true

		if rel != nil {
			rel.R.Budgets = BudgetSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("budget has no relationship %q", name)
	}
}

type budgetPreloader struct {
	Category  func(...psql.PreloadOption) psql.Preloader
	Household func(...psql.PreloadOption) psql.Preloader
}

func buildBudgetPreloader() budgetPreloader {
	return budgetPreloader{
		Category: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Category, CategorySlice](psql.PreloadRel{
				Name: "Category",
				Sides: []psql.PreloadSide{
					{
						From:        Budgets,
						To:          Categories,
						FromColumns: []string{"household_id", "category_id"},
						ToColumns:   []string{"household_id", "id"},
					},
				},
			}, Categories.Columns.Names(), categoryScanMapperNullable, opts...)
		},
		Household: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Household, HouseholdSlice](psql.PreloadRel{
				Name: "Household",
				Sides: []psql.PreloadSide{
					{
						From:        Budgets,
						To:          Households,
						FromColumns: []string{"household_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Households.Columns.Names(), householdScanMapperNullable, opts...)
		},
	}
}

type budgetThenLoader[Q orm.Loadable] struct {
	Category  func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Household func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildBudgetThenLoader[Q orm.Loadable]() budgetThenLoader[Q] {
	type CategoryLoadInterface interface {
		LoadCategory(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type HouseholdLoadInterface interface {
		LoadHousehold(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return budgetThenLoader[Q]{
		Category: thenLoadBuilder[Q](
			"Category",
			func(ctx context.Context, exec bob.Executor, retrieved CategoryLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCategory(ctx, exec, mods...)
			},
		),
		Household: thenLoadBuilder[Q](
			"Household",
			func(ctx context.Context, exec bob.Executor, retrieved HouseholdLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadHousehold(ctx, exec, mods...)
			},
		),
	}
}

// LoadCategory loads the budget's Category into the .R struct
func (o *Budget) LoadCategory(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Category = nil
	o.R.Loaded.Category = false

	related, err := o.Category(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.Budgets = BudgetSlice{o}

	o.R.Category = related
	o.R.Loaded.Category = true
	return nil
}

// LoadCategory loads the budget's Category into the .R struct
func (os BudgetSlice) LoadCategory(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	categories, err := os.Category(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Category = nil
		o.R.Loaded.Category = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range categories {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}
			if !o.CategoryID.Valid {
				continue
			}

			if !(o.CategoryID.Valid && o.CategoryID.V == rel.ID) {
				continue
			}

			rel.R.Budgets = append(rel.R.Budgets, o)

			o.R.Category = rel
			break
		}
	}

	return nil
}

// LoadHousehold loads the budget's Household into the .R struct
func (o *Budget) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Household = nil
	o.R.Loaded.Household = false

	related, err := o.Household(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.Budgets = BudgetSlice{o}

	o.R.Household = related
	o.R.Loaded.Household = true
	return nil
}

// LoadHousehold loads the budget's Household into the .R struct
func (os BudgetSlice) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	households, err := os.Household(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Household = nil
		o.R.Loaded.Household = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	budgetByKey := make(map[uuid.UUID][]*Budget, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		budgetByKey[o.HouseholdID] = append(budgetByKey[o.HouseholdID], o)
	}

	for _, rel := range households {

		owners, ok := budgetByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Household != nil {
				continue
			}

			rel.R.Budgets = append(rel.R.Budgets, o)

			o.R.Household = rel

		}
	}

	return nil
}

type budgetJoins[Q dialect.Joinable] struct {
	typ       string
	Category  modAs[Q, categoryColumns]
	Household modAs[Q, householdColumns]
}

func (j budgetJoins[Q]) aliasedAs(alias string) budgetJoins[Q] {
	return buildBudgetJoins[Q](buildBudgetColumns(alias), j.typ)
}

func buildBudgetJoins[Q dialect.Joinable](cols budgetColumns, typ string) budgetJoins[Q] {
	return budgetJoins[Q]{
		typ: typ,
		Category: modAs[Q, categoryColumns]{
			c: Categories.Columns,
			f: func(to categoryColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Categories.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.CategoryID),
					))
				}

				return mods
			},
		},
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
	}
}
